package floydwarshall.format;

import floydwarshall.algorithm.AllPairsShortestPaths;

import java.util.function.Function;

/**
 * Renders an {@link AllPairsShortestPaths} distance matrix as human-readable
 * text. Unreachable pairs are shown with a configurable token (default
 * {@code "INF"}), each weight is rendered with a configurable function (default
 * {@link String#valueOf}), and columns are right-aligned for readability.
 *
 * @param <W> the weight type
 */
public final class DistanceMatrixFormatter<W> {

    private final String unreachableToken;
    private final Function<W, String> renderer;

    public DistanceMatrixFormatter() {
        this("INF", String::valueOf);
    }

    public DistanceMatrixFormatter(String unreachableToken) {
        this(unreachableToken, String::valueOf);
    }

    public DistanceMatrixFormatter(String unreachableToken, Function<W, String> renderer) {
        this.unreachableToken = unreachableToken;
        this.renderer = renderer;
    }

    /** Formats the distance matrix with right-aligned, evenly spaced columns. */
    public String format(AllPairsShortestPaths<W> result) {
        int n = result.vertexCount();
        String[][] cells = new String[n][n];
        int width = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                String text = result.distance(i, j).map(renderer).orElse(unreachableToken);
                cells[i][j] = text;
                width = Math.max(width, text.length());
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (j > 0) {
                    sb.append(' ');
                }
                sb.append(pad(cells[i][j], width));
            }
            sb.append(System.lineSeparator());
        }
        return sb.toString();
    }

    private static String pad(String text, int width) {
        return " ".repeat(width - text.length()) + text;
    }
}
